const companies = [
  { name: 'Example Co', token: 'exampleco' },
  { name: 'Acme Inc', token: 'acmeinc' },
];

const allJobs = [];

for (const company of companies) {
  try {
    const response = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://boards-api.greenhouse.io/v1/boards/${company.token}/jobs?content=true`,
    });

    if (response.jobs) {
      for (const job of response.jobs) {
        allJobs.push({
          json: {
            source: 'greenhouse',
            company: company.name,
            title: job.title,
            location: job.location?.name || 'Unknown',
            url: job.absolute_url,
            department: job.departments?.[0]?.name || '',
            description_snippet: (job.content || '').substring(0, 500),
            external_id: `gh_${company.token}_${job.id}`,
            date_found: new Date().toISOString().split('T')[0],
          }
        });
      }
    }
  } catch (e) {
    allJobs.push({
      json: { error: `Failed for ${company.name}: ${e.message}` }
    });
  }
}

return allJobs;

