const companies = [
  { name: 'Example Co', token: 'exampleco' },
  { name: 'Acme Inc', token: 'acmeinc' },
];

const allJobs = [];

for (const company of companies) {
  try {
    const response = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://api.ashbyhq.com/posting-api/job-board/${company.token}`,
      headers: { 'Accept': 'application/json' },
    });

    if (response.jobs) {
      for (const job of response.jobs) {
        allJobs.push({
          json: {
            source: 'ashby',
            company: company.name,
            title: job.title,
            location: job.location || 'Unknown',
            url: job.applyUrl || `https://jobs.ashbyhq.com/${company.token}/${job.id}`,
            department: job.department || '',
            description_snippet: (job.descriptionPlain || '').substring(0, 500),
            external_id: `ash_${company.token}_${job.id}`,
            date_found: new Date().toISOString().split('T')[0],
          }
        });
      }
    }
  } catch (e) {
    allJobs.push({
      json: { error: `Failed for ${company.name}: ${e.message}` }
    });
  }
}

return allJobs;

const jobs = $input.all();

// TITLE EXCLUSIONS — roles that don't fit your profile
const excludeTitles = [
  // Engineering & technical
  'engineer', 'developer', 'software', 'frontend', 'backend', 'fullstack',
  'devops', 'sre', 'infrastructure', 'architect', 'platform eng',
  // Design
  'designer', 'ux ', 'ui ', 'design manager', 'graphic design',
  // Legal & compliance
  'legal', 'counsel', 'compliance', 'paralegal', 'attorney', 'regulatory',
  'aml ', 'anti-money', 'money laundering', 'financial crimes',
  // Finance & accounting
  'accountant', 'accounting', 'tax ', 'audit', 'bookkeeper', 'controller',
  'accounts receivable', 'accounts payable', 'treasury', 'billing',
  'reconciliation', 'safeguarding',
  // HR & recruiting
  'recruiter', 'recruiting', 'sourcer', 'people partner', 'employee relations',
  'compensation analyst', 'compensation design',
  // Admin & facilities
  'administrative', 'receptionist', 'office manager', 'facilities',
  'coordinator', 'executive assistant',
  // Sales execution (quota-carrying)
  'account executive', 'sales development rep', 'sdr', 'bdr',
  'account development rep', 'regional vp of', 'rvp,',
  'channel sales', 'sales manager',
  // Data science & analytics (technical)
  'data scientist', 'data engineer', 'machine learning', 'ml engineer',
  'data analyst',
  // Customer support & ops specialists
  'support specialist', 'collections specialist', 'collections program',
  'customer funds', 'contracting operations',
  // Clinical / medical
  'nurse', 'physician', 'therapist', 'clinical',
  // Internships
  'intern', 'internship',
  // Other non-fit
  'content writer', 'data writer', 'copywriter',
  'event manager', 'events manager', 'corporate events',
  // Product management (explicitly not targeting)
'product manager', 'product lead', 'product management',
'staff product manager', 'senior product manager', 'agent product manager',
// Revenue/pricing ops
'revenue operations', 'rev ops', 'deal pricing', 'pricing manager',
// Investor/finance-titled roles
'forward deployed investor',
];

// LOCATION WHITELIST — only keep these geographies
const allowedLocations = [
  'singapore', 'hong kong',
  'us', 'united states', 'america',
  'san francisco', 'new york', 'nyc', 'sf,', 'seattle', 'chicago',
  'boston', 'denver', 'austin', 'los angeles', 'la,',
  'south san francisco', 'menlo park', 'palo alto', 'mountain view',
  'remote', 'canada', 'toronto',
  'n/a', 'unknown',
];

const filtered = jobs.filter(job => {
  const title = (job.json.title || '').toLowerCase();
  const location = (job.json.location || '').toLowerCase();

  // Check title exclusions
  for (const kw of excludeTitles) {
    if (title.includes(kw)) return false;
  }

  // Check location whitelist — must match at least one
  let locationMatch = false;
  for (const kw of allowedLocations) {
    if (location.includes(kw)) {
      locationMatch = true;
      break;
    }
  }
  if (!locationMatch) return false;

  return true;
});

return filtered;

const newJobs = $input.all();

// Build a set of external IDs already in Airtable
let existingIds = new Set();
try {
  const airtableRecords = $("Airtable Search Jobs").all();
  for (const rec of airtableRecords) {
    // Airtable returns fields under rec.json.fields
    const eid = rec.json.fields?.['External ID'] || rec.json['External ID'] || '';
    if (eid) existingIds.add(eid);
  }
} catch (e) {
  // If Airtable node returned nothing or errored, treat as empty
  // (all jobs will be considered "new")
}

// Filter: keep jobs whose external_id is NOT already in Airtable
const deduped = newJobs.filter(job => {
  // *** FIX: upstream nodes use "external_id" (lowercase, underscore) ***
  const eid = job.json.external_id || '';
  return eid !== '' && !existingIds.has(eid);
});

if (deduped.length === 0) {
  return [{ json: { _no_new_jobs: true, message: 'No new jobs found today' } }];
}

return deduped;

const jobs = $input.all();

let companyMap = {};
try {
  const companies = $("Lookup Companies").all();
  for (const c of companies) {
    const name = (c.json.fields?.["Company Name"] || c.json["Company Name"] || '').toLowerCase().trim();
    const id = c.json.id || '';
    if (name && id) companyMap[name] = id;
  }
} catch (e) {}

const enriched = jobs.map(job => {
  const j = job.json;
  const companyLower = (j.company || '').toLowerCase().trim();
  const companyId = companyMap[companyLower] || null;

  return {
    json: {
      ...j,
      company_record_id: companyId,
      company_name_text: j.company || '',
      // role_family already set by Filter & Score — don't overwrite
    }
  };
});

return enriched;

const items = $input.all();
const passed = items.filter(item => item.json.status !== 'Rejected');

if (passed.length === 0) {
  return [{ json: { _no_new_jobs: true, message: 'All jobs filtered out' } }];
}

return passed;

const response = $input.all()[0].json;
const buildPromptOutput = $("Build Prompt").all()[0].json;
const originalJobs = buildPromptOutput.originalJobs;
const batchCount = buildPromptOutput.batchCount;

// Handle API error
const responseText = response?.content?.[0]?.text || '';
if (!responseText) {
  return originalJobs.map(j => ({
    json: {
      ...j,
      fit_score: '',
      recommended_action: '',
      role_family: 'Other',
      fit_rationale: `ERROR: Empty API response`,
      status: 'Rejected',
    }
  }));
}

// Parse response
const results = [];
for (let i = 0; i < batchCount; i++) {
  const n = i + 1;
  const fitMatch = responseText.match(new RegExp(`JOB_${n}\\s*Fit Score:\\s*(.+)`));
  const actMatch = responseText.match(new RegExp(`JOB_${n}\\s*Recommended Action:\\s*(.+)`));
  const famMatch = responseText.match(new RegExp(`JOB_${n}\\s*Role Family:\\s*(.+)`));
  const ratMatch = responseText.match(new RegExp(`JOB_${n}\\s*Rationale:\\s*(.+)`));
  const fitScore = fitMatch?.[1]?.trim() || 'Skip';
  const recAction = actMatch?.[1]?.trim() || 'Skip';

  results.push({
    json: {
      ...originalJobs[i],
      fit_score: fitScore === 'Skip' ? '' : fitScore,
      recommended_action: recAction === 'Skip' ? '' : recAction,
      role_family: famMatch?.[1]?.trim() || 'Other',
      fit_rationale: ratMatch?.[1]?.trim() || '',
      status: fitScore === 'Skip' ? 'Rejected' : 'New',
    }
  });
}

return results;

const batch = $input.all();

// Pass through no-jobs flag
if (batch.length === 1 && batch[0].json._no_new_jobs) {
  return batch;
}

const systemPrompt = `You are a job scoring system. You will receive multiple jobs numbered JOB_1, JOB_2, etc.
For EACH job, return EXACTLY 4 lines prefixed with the job number. No other text.
Candidate: [YOUR PROFILE — e.g. MBA (YEAR), ex-CONSULTING FIRM (N yrs, INDUSTRIES), LANGUAGES, based in CITY]. Targeting [YOUR TARGET ROLES] at [YOUR TARGET SECTORS].
SKIP immediately if: Engineering, Product Management, Product Lead, Sales (AE/SDR/BDR), Solutions/Technical Account Mgmt, Design, HR, Legal, Finance/Accounting, Support, Customer Success, Comms/PR, Demand Gen, Field Marketing, Events, Data Science/ML, Revenue Operations, Deal Pricing, or if seniority requires 10+ years (Director+ at companies with 1000+ employees, VP/C-suite anywhere).
For each job respond EXACTLY in this format:
JOB_N Fit Score: [Strong Fit / Medium Fit / Weak Fit / Skip]
JOB_N Recommended Action: [Apply Now / Network First / Watchlist / Skip]
JOB_N Role Family: [Strategy / Ops / BizOps / Analytics / GTM / PMM / Chief of Staff / Other]
JOB_N Rationale: [1 sentence]`;

const userMessage = batch.map((item, idx) => {
  const j = item.json;
  return `JOB_${idx + 1}:
Title: ${j.title || ''}
Company: ${j.company || ''}
Location: ${j.location || ''}
Department: ${j.department || ''}
Description: ${(j.description_snippet || '').substring(0, 400)}`;
}).join('\n\n');

// Output one item containing the API request body and original jobs
return [{
  json: {
    requestBody: {
      model: 'claude-haiku-4-5-20251001',
      max_tokens: 700,
      system: systemPrompt,
      messages: [{ role: 'user', content: userMessage }],
    },
    batchCount: batch.length,
    originalJobs: batch.map(b => b.json),
  }
}];
